import os
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def extract_layout_elements(
    document_path: str,
    model_id: str = "prebuilt-layout",
    endpoint: Optional[str] = None,
    api_key: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Extract layout elements from a document using Azure AI Document Intelligence.

    Returns a dictionary with pages, paragraphs, tables, selection marks, and raw layout data.
    """
    endpoint = endpoint or os.getenv("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    api_key = api_key or os.getenv("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint:
        raise ValueError("Missing Azure Document Intelligence endpoint.")
    if not api_key:
        raise ValueError("Missing Azure Document Intelligence API key.")

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(api_key))

    with open(document_path, "rb") as f:
        poller = client.begin_analyze_document(model_id=model_id, body=f)

    result = poller.result()

    pages: List[Dict[str, Any]] = []
    for page in getattr(result, "pages", []) or []:
        page_obj: Dict[str, Any] = {
            "page_number": getattr(page, "page_number", None),
            "width": getattr(page, "width", None),
            "height": getattr(page, "height", None),
            "unit": getattr(page, "unit", None),
            "words": [],
            "lines": [],
        }

        for line in getattr(page, "lines", []) or []:
            page_obj["lines"].append(
                {
                    "content": getattr(line, "content", None),
                    "polygon": _polygon_to_list(getattr(line, "polygon", None)),
                }
            )

        for word in getattr(page, "words", []) or []:
            page_obj["words"].append(
                {
                    "content": getattr(word, "content", None),
                    "confidence": getattr(word, "confidence", None),
                    "polygon": _polygon_to_list(getattr(word, "polygon", None)),
                }
            )

        pages.append(page_obj)

    paragraphs: List[Dict[str, Any]] = []
    for paragraph in getattr(result, "paragraphs", []) or []:
        paragraphs.append(
            {
                "content": getattr(paragraph, "content", None),
                "role": getattr(paragraph, "role", None),
                "spans": _spans_to_list(getattr(paragraph, "spans", None)),
                "bounding_regions": _bounding_regions_to_list(getattr(paragraph, "bounding_regions", None)),
            }
        )

    tables: List[Dict[str, Any]] = []
    for table in getattr(result, "tables", []) or []:
        cells: List[Dict[str, Any]] = []
        for cell in getattr(table, "cells", []) or []:
            cells.append(
                {
                    "kind": getattr(cell, "kind", None),
                    "row_index": getattr(cell, "row_index", None),
                    "column_index": getattr(cell, "column_index", None),
                    "row_span": getattr(cell, "row_span", None),
                    "column_span": getattr(cell, "column_span", None),
                    "content": getattr(cell, "content", None),
                    "spans": _spans_to_list(getattr(cell, "spans", None)),
                    "bounding_regions": _bounding_regions_to_list(getattr(cell, "bounding_regions", None)),
                }
            )

        tables.append(
            {
                "row_count": getattr(table, "row_count", None),
                "column_count": getattr(table, "column_count", None),
                "cells": cells,
                "spans": _spans_to_list(getattr(table, "spans", None)),
                "bounding_regions": _bounding_regions_to_list(getattr(table, "bounding_regions", None)),
            }
        )

    selection_marks: List[Dict[str, Any]] = []
    for mark in getattr(result, "selection_marks", []) or []:
        selection_marks.append(
            {
                "state": getattr(mark, "state", None),
                "confidence": getattr(mark, "confidence", None),
                "polygon": _polygon_to_list(getattr(mark, "polygon", None)),
                "span": _span_to_dict(getattr(mark, "span", None)),
                "bounding_regions": _bounding_regions_to_list(getattr(mark, "bounding_regions", None)),
            }
        )

    output: Dict[str, Any] = {
        "content": getattr(result, "content", None),
        "pages": pages,
        "paragraphs": paragraphs,
        "tables": tables,
        "selection_marks": selection_marks,
        "raw_result": result,
    }

    return output


def _polygon_to_list(polygon: Any) -> Optional[List[float]]:
    if polygon is None:
        return None
    try:
        return [float(v) for v in polygon]
    except TypeError:
        return None


def _span_to_dict(span: Any) -> Optional[Dict[str, Any]]:
    if span is None:
        return None
    return {
        "offset": getattr(span, "offset", None),
        "length": getattr(span, "length", None),
    }


def _spans_to_list(spans: Any) -> List[Dict[str, Any]]:
    if not spans:
        return []
    return [_span_to_dict(span) for span in spans if span is not None]


def _bounding_regions_to_list(bounding_regions: Any) -> List[Dict[str, Any]]:
    if not bounding_regions:
        return []
    regions: List[Dict[str, Any]] = []
    for region in bounding_regions:
        if region is None:
            continue
        regions.append(
            {
                "page_number": getattr(region, "page_number", None),
                "polygon": _polygon_to_list(getattr(region, "polygon", None)),
            }
        )
    return regions
